<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Palette Generator','description'=>'Create a harmonious color palette and copy HEX values instantly.','url'=>'https://smarttoolz.in/tools/color-palette/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">COLOR PALETTE</span><h1>Color Palette</h1><p>Generate five matching colors and copy their HEX codes.</p></section><section class="tool-workspace"><div class="tool-panel"><div id="palette" style="display:grid;grid-template-columns:repeat(5,1fr);gap:8px"></div><button id="go" class="tool-btn" style="margin-top:18px">Generate Palette</button><p id="msg"></p></div></section></main><script>(()=>{const p=document.getElementById('palette'),m=document.getElementById('msg');function gen(){p.innerHTML='';for(let i=0;i<5;i++){let c='#'+Math.floor(Math.random()*16777215).toString(16).padStart(6,'0'),d=document.createElement('button');d.textContent=c;d.style='height:110px;border:0;border-radius:12px;cursor:pointer;font-weight:800;background:'+c+';color:#fff;text-shadow:0 1px 3px #000';d.onclick=async()=>{await navigator.clipboard.writeText(c);m.textContent=c+' copied.'};p.append(d)}}document.getElementById('go').onclick=gen;gen()})();</script><?php smarttoolz_tool_page_end(); ?>